// 模板: <div><span>static text</span><p>{{ msg }}</p></div>

// ===================== Vue 2 编译结果 =====================
// 每次渲染重新创建所有 VNode，全量 diff
function render() {
  return _c('div', [
    _c('span', [_v('static text')]),   // 静态节点每次重建
    _c('p', [_v(_s(msg))])              // 动态节点，无标记
  ]);
}

// ===================== Vue 3 编译结果 =====================
// 静态节点提升为常量 + 动态节点带 PatchFlag
const _hoisted_1 = /*#__PURE__*/ _createElementVNode(
  'span', null, 'static text', -1 /* HOISTED */
);
// ↑ 模块级常量，渲染函数每次执行时直接引用，不重新创建

function render(_ctx, $props, $setup, $data, $options) {
  return (_openBlock(), _createElementBlock('div', null, [
    _hoisted_1,  // 复用提升的静态 VNode
    _createElementVNode('p', null, _toDisplayString(_ctx.msg), 1 /* TEXT */)
    //                                                   PatchFlag=1 ↑ 只比较文本
  ]));
}
// _openBlock() 把后续创建的带 PatchFlag 的 VNode 收集到 Block 的 dynamicChildren

// ===================== 事件缓存 =====================
// 模板: <button @click="count++">Add</button>
function render(_ctx, $cache) {
  return _createElementVNode('button', {
    // 缓存到 $cache[0]，后续渲染复用同一函数引用
    onClick: $cache[0] || ($cache[0] = () => { _ctx.count++; })
  }, 'Add');
}

// ===================== Block Tree 运行时 =====================
// patch 阶段如果 VNode 有 dynamicChildren，只遍历动态节点
function patchElement(oldVNode, newVNode) {
  if (newVNode.dynamicChildren) {
    // 只 patch 动态子节点，跳过静态子树
    patchBlockChildren(
      oldVNode.dynamicChildren,
      newVNode.dynamicChildren
    );
  } else {
    // 兜底：全量 diff 子节点
    patchChildren(oldVNode, newVNode);
  }
}
